"""Common CONFIG source expansion; profile records are generated by the disk builder."""
from pathlib import Path
from system_layout import expand_layout
from shared_ui import expand_config_ui
ROOT=Path(__file__).resolve().parents[1]
def expanded_source(generated_root=None):
 text='FDBRTON EQU 1\n'+expand_layout((ROOT/'src/utilities/config.mac').read_text())
 for name in ('sysgen','common','fdbread'):
  text=text.replace('        INCLUDE disk/'+name+'.inc',(ROOT/'src/utilities/disk'/(name+'.inc')).read_text())
 for name in ('validation','iobyte'):
  text=text.replace('; @config-'+name+'@',((Path(generated_root) if generated_root else ROOT)/'build/utilities'/('config-'+name+'.inc')).read_text())
 text=text.replace('; @monitor-console@',(ROOT/'src/utilities/common/monitorconsole.inc').read_text())
 from system_layout import CONTEXT
 if CONTEXT:
  text=text.replace('Requires BetterCP/M disk BIOS ABI 5 (four drives).', 'Requires matching BetterCP/M private build.')
 from component_registry import utility_identities
 from component_identity import title
 from utility_versions import display_development
 version,revision=utility_identities()['CONFIG']
 lines=[title('CONFIG',version,revision,development=display_development('utility:CONFIG')),
        '  - - -',' | BetterCP/M Utilities',' | System Configuration',' |',
        ' |   Usage: CONFIG [options]','', '   Options:',
        '     /SHOW                 Show active and startup settings.',
        '     /STARTUP="text"       Set pending cold-boot command.',
        '     /DEFAULT              Reset pending startup command.',
        '     /IOBYTE=n             Save boot routes; live unchanged.',
        '     /PHYSICAL=n fields    Set physical profile (0-3).',
        '     /LOGICAL=d /PHYSICAL=n /FORMAT="name"   Bind drive B-D.',
        '     /LOGICAL=d /UNBIND     Remove binding (B-D).',
        '     /EDIT=d fields        Edit disk definition (B-D).',
        '     Physical: /TYPE /TRACKS /SIDES /STEP /SPINUP /SETTLE',
        '     Edit: /PHYSICAL /SPT /BSH /BLM /EXM /DSM /DRM /AL0 /AL1',
        '           /CKS /OFF /CYLINDERS /SECTORS /SIZE /FLAGS /SIZEMAP',
        '           /SLOT /ID /CODE   (all fields use =value)',
        '     /H /HELP              Display this help.',
        '     /VER                  Display utility identification.',
        'For detailed help, see HELP CONFIG']
 help_data='CQ_TEXT:\n'+''.join(
     ("        DB '"+line.replace("'","''")+"',13,10\n") if line else
     '        DB 13,10\n' for line in lines)+"        DB '$'\n"
 appendix=(ROOT/'src/utilities/common/confighelp.inc').read_text().replace(
     '; @config-help-text@',help_data)
 text=text.replace('; @config-pds@',(ROOT/'src/utilities/common/configpdsload.inc').read_text())
 text=text.replace('; @config-help@',appendix)
 import zlib
 overlay=ROOT/'build/utilities/PDSCONF.OVL'
 crc=zlib.crc32(overlay.read_bytes()[:1792]) if overlay.exists() else 0
 text=text.replace('; @pds-overlay-crc@','        DB '+','.join(str(x) for x in crc.to_bytes(4,'little')))
 return expand_config_ui(text)


def validate_layout(image, listing):
 """Help is disposable above the 256-byte private stack (3F00h..3FFFh)."""
 import re
 def symbol(name):
  match=re.search(r'^([0-9a-f]{4})\s+.*?\b'+name+':',listing,re.M|re.I)
  if not match:raise ValueError('CONFIG listing lacks '+name)
  return int(match[1],16)
 if symbol('CF_MAIN_END')>0x3f00 or symbol('CF_QUERY')!=0x4000:
  raise ValueError('CONFIG code/help overlaps its private stack')
 if 0x100+len(image)>0xac00:
  raise ValueError('CONFIG help exceeds existing minimum transient memory')


def build_image(assembler, text, out):
 """Bind one matching PDS settings overlay to CONFIG's existing callbacks."""
 import re, zlib
 from build_ccp import assemble
 from build_z80pack_image import symbols
 image=assemble(assembler,text,out/'CONFIG.COM',out/'config.lst',0x100)
 labels=symbols(out/'config.lst')
 callbacks=('STSTATE','STFETCH','STSAVEINVALID','HEADER','PUTS','PUTC',
            'CRLF','CHOICE','STSUBFCB','STDIRTY','MAIN')
 prefix=''.join(f'{name} EQU 0{labels[name]:04X}H\n' for name in callbacks)
 prefix+='STPEND EQU 0A9A0H\nBDOS EQU 5\n'
 overlay=('        INCLUDE layout.inc\n'+prefix+
          '        ASEG\n        ORG 09000H\n'+
          '\n'.join('        JP '+name for name in
                    ('PC_VALIDATE','PD_UPGRADE','PD_KEEP','PD_RESTORE','PD_SNAPSHOT','PD_MENU','STDEFAULT','STCHECKSUM','STFCBRESET'))+
          '\n        INCLUDE command-record.inc\n        INCLUDE pds-directory.inc\n'+
          (ROOT/'src/utilities/common/configpds.inc').read_text()+'\n        END\n')
 data=assemble(assembler,overlay,out/'pdsconf.bin',out/'pdsconf.lst',0x9000)
 if len(data)>2048:
  raise ValueError('PDS configuration overlay exceeds its existing track-buffer window')
 data=data.ljust(2048,b'\0')
 (out/'PDSCONF.OVL').write_bytes(data)
 crc=','.join(str(x) for x in zlib.crc32(data[:1792]).to_bytes(4,'little'))
 text=re.sub(r'PD_EXPECT:\n[^\n]*', 'PD_EXPECT:\n        DB '+crc, text)
 image=assemble(assembler,text,out/'CONFIG.COM',out/'config.lst',0x100)
 if any(symbols(out/'config.lst')[name]!=labels[name] for name in callbacks):
  raise ValueError('CONFIG callbacks moved during overlay binding')
 return image
